use serde_json::json;use sha2::{Digest,Sha256};use std::{hint::black_box,time::Instant};use zopro_bn254::{Fp,FpConfig,FqConfig,FrConfig,ifma8::Ifma8};
#[inline(always)]fn mul<C:FpConfig,const M:bool,const ALT:bool>(a:Ifma8<C,M>,b:Ifma8<C,M>)->Ifma8<C,M>{#[cfg(paired_kernel)]if ALT{return a.mul_lookahead(&b)}a.mul(&b)}
#[inline(always)]fn sum<C:FpConfig,const M:bool,const ALT:bool>(a:Ifma8<C,M>,b:Ifma8<C,M>,c:Ifma8<C,M>,d:Ifma8<C,M>)->Ifma8<C,M>{#[cfg(paired_kernel)]if ALT{return a.sum2_lookahead(&b,&c,&d)}a.sum2(&b,&c,&d)}
#[inline(never)]fn chain<C:FpConfig,const M:bool,const ALT:bool>(mut x:Ifma8<C,M>,b:Ifma8<C,M>,c:Ifma8<C,M>,n:usize)->[Ifma8<C,M>;4]{for _ in 0..n{x=mul::<C,M,ALT>(x,b).add(&c);}[black_box(x);4]}
#[inline(never)]fn streams<C:FpConfig,const M:bool,const ALT:bool>(mut x:[Ifma8<C,M>;4],b:Ifma8<C,M>,c:Ifma8<C,M>,n:usize)->[Ifma8<C,M>;4]{for _ in 0..n{for x in &mut x{*x=mul::<C,M,ALT>(*x,b).add(&c);}}black_box(x)}
#[inline(never)]fn fused<C:FpConfig,const M:bool,const ALT:bool>(mut x:Ifma8<C,M>,b:Ifma8<C,M>,c:Ifma8<C,M>,d:Ifma8<C,M>,n:usize)->[Ifma8<C,M>;4]{for _ in 0..n{x=sum::<C,M,ALT>(x,b,c,d);}[black_box(x);4]}
fn execute<C:FpConfig,const M:bool,const ALT:bool>(pattern:&str,n:usize,x:[Ifma8<C,M>;4],b:Ifma8<C,M>,c:Ifma8<C,M>,d:Ifma8<C,M>)->[Ifma8<C,M>;4]{match pattern{"chain"=>chain::<C,M,ALT>(x[0],b,c,n),"streams4"=>streams::<C,M,ALT>(x,b,c,n),"fused"=>fused::<C,M,ALT>(x[0],b,c,d,n),_=>panic!("pattern")}}
fn run<C:FpConfig,const M:bool,const ALT:bool>(mode:&str,field:&str,pattern:&str,n:usize){let mut seed=0xc0ac29b7c97c50ddu64;let mut next=||{let mut b=[0u8;32];for v in b.chunks_mut(8){seed^=seed<<13;seed^=seed>>7;seed^=seed<<17;v.copy_from_slice(&seed.to_le_bytes());}Fp::<C>::from_le_bytes_mod_order(&b)};let raw:[[Fp<C>;8];4]=std::array::from_fn(|_|std::array::from_fn(|_|next()));let rb=std::array::from_fn(|_|next());let rc=std::array::from_fn(|_|next());let rd=std::array::from_fn(|_|next());let x=raw.map(|v|Ifma8::<C,M>::new(&v));let b=Ifma8::<C,M>::new(&rb);let c=Ifma8::<C,M>::new(&rc);let d=Ifma8::<C,M>::new(&rd);
    for _ in 0..3{black_box(execute::<C,M,ALT>(pattern,2000,black_box(x),b,c,d));}let start=Instant::now();let out=execute::<C,M,ALT>(pattern,n,black_box(x),b,c,d);let elapsed=start.elapsed();let actual=out.map(|v|v.get());
    for stream in 0..4{for lane in 0..8{let init=raw[if pattern=="streams4"{stream}else{0}][lane];let b=rb[lane];let c=if pattern=="fused"{rc[lane]*rd[lane]}else{rc[lane]};let power=b.pow(&[n as u64]);let geometric=if b==Fp::<C>::ONE{Fp::<C>::from(n as u64)}else{(power-Fp::<C>::ONE)*(b-Fp::<C>::ONE).inverse().unwrap()};assert_eq!(actual[stream][lane],init*power+c*geometric);}}
    let bytes:Vec<_>=actual.iter().flatten().flat_map(|v|v.to_canonical().into_iter().flat_map(u64::to_le_bytes)).collect();let divisor=n*8*if pattern=="streams4"{4}else{1};println!("RESULT {}",json!({"mode":mode,"field":field,"mixed":M,"pattern":pattern,"iterations":n,"prime_calls":3,"prime_iterations":2000,"elapsed_ns":elapsed.as_nanos(),"ns_per_unit":elapsed.as_nanos()as f64/divisor as f64,"checked_fields":32,"output_sha256":format!("{:x}",Sha256::digest(bytes)),"internally_verified":true,"conversion_timed":false,"SDK_requests":0}));}
fn dispatch<C:FpConfig,const M:bool>(mode:&str,field:&str,pattern:&str,n:usize){if mode=="paired"{run::<C,M,true>(mode,field,pattern,n)}else{assert_eq!(mode,"ordinary");run::<C,M,false>(mode,field,pattern,n)}}
fn main(){let args:Vec<_>=std::env::args().collect();assert_eq!(args.len(),6);let n=args[5].parse().unwrap();assert!(n>0);let m=&args[1];let field=&args[2];let pattern=&args[4];match(field.as_str(),args[3].as_str()){
    ("Fq","R256")=>dispatch::<FqConfig,true>(m,field,pattern,n),("Fq","R260")=>dispatch::<FqConfig,false>(m,field,pattern,n),("Fr","R256")=>dispatch::<FrConfig,true>(m,field,pattern,n),("Fr","R260")=>dispatch::<FrConfig,false>(m,field,pattern,n),_=>panic!("configuration")}}
